const rule = (pattern, plain, mechanism, source, search) => ({ pattern, plain, mechanism, source, search });

const rules = [
  rule(/register layer/i, "Đây là lớp thấp nhất: nó chỉ đặt tên cho vùng nhớ phần cứng, offset và bit field. Nó không biết LED, nút nhấn hay yêu cầu sản phẩm.", "Tách lớp này giúp kiểm tra địa chỉ bằng offsetof/static assert trước khi chạy board. Nếu địa chỉ sai, mọi API phía trên đều sai dù thuật toán đúng.", "S32K1xx RM · Ch.3 và register map của từng peripheral", "memory map, base address, register offset, reserved"),
  rule(/driver layer/i, "Driver biến một hành động như ‘đặt pin HIGH’ thành chuỗi kiểm tra và truy cập register có thứ tự.", "Driver generic nhận instance/pin/channel, kiểm tra input và trạng thái rồi thao tác PCC/PORT/GPIO hoặc peripheral tương ứng. Nó không sở hữu tên linh kiện trên board.", "RM · functional description và initialization sequence của peripheral", "initialization sequence, functional description"),
  rule(/board layer|board net|polarity|active-low|active-high/i, "Board layer trả lời câu hỏi chân đó đang nối với linh kiện nào và mức điện nào mang ý nghĩa ON/pressed. Hai board dùng cùng MCU có thể khác hoàn toàn ở lớp này.", "Schematic quyết định net, điện trở, jumper và polarity. Driver chỉ trả mức điện; board API chuyển mức điện thành ý nghĩa logic.", "SCH-28810 Rev.B · sheet chứa RGB, button, potentiometer hoặc CAN transceiver", "net label, RGB LED, SW2, SW3, potentiometer, CANH, CANL"),
  rule(/application/i, "Application mô tả hành vi người dùng nhìn thấy, ví dụ nhấn nút đổi chế độ. Nó không nên biết địa chỉ hoặc bit field.", "Application gọi board/driver API. Khi pin hoặc MCU thay đổi, phần lớn application vẫn giữ nguyên vì chi tiết register bị che ở lớp dưới.", "Thiết kế phần mềm; đối chiếu RM chỉ xảy ra trong register/driver layer", "API contract, dependency direction"),
  rule(/schematic/i, "Schematic là bản đồ dây điện của board: linh kiện nào nối với chân nào, qua điện trở/jumper nào và có pull bên ngoài hay không.", "Schematic không định nghĩa PCR hay PDDR. Nó cung cấp sự thật vật lý để chọn đúng pin, polarity và điểm đo.", "S32K144EVB schematic · SCH-28810 Rev.B", "net label, MCU pin, resistor, jumper, stuffing option"),
  rule(/datasheet/i, "Datasheet cho biết chip có tính năng gì và được phép hoạt động trong giới hạn điện, clock và timing nào.", "Nó dùng để kiểm tra cấu hình có hợp lệ về điện/timing, nhưng không đủ để viết chuỗi register. Chuỗi register phải lấy từ RM.", "S32K1xx Datasheet Rev.15", "electrical characteristics, operating conditions, ADC specifications"),
  rule(/reference manual|\bRM\b/i, "Reference Manual là tài liệu chính để viết driver: base address, offset, reset value, access type, bit field và trình tự hoạt động.", "Luôn đọc phần chip-specific trước phần IP generic. Một hình generic có thể vẽ nhiều bit/channel hơn biến thể S32K144 thực sự hỗ trợ.", "S32K1xx RM Rev.14.2", "memory map, register description, functional description, initialization"),
  rule(/ARM ARM|NVIC|SysTick|exception/i, "ARM ARM mô tả phần lõi Cortex-M: CPU vào exception thế nào, NVIC phân xử ra sao và SysTick đếm thế nào. Nó không định nghĩa peripheral NXP.", "IRQ từ PORT/ADC/CAN bắt đầu ở peripheral NXP, đi qua NVIC rồi mới thành exception ở core. Vì vậy thường phải dùng cả RM và ARM ARM cho một đường interrupt.", "ARM DDI0403E.e · B1.5 và B3.4; Cortex-M4 Generic User Guide", "exception entry, vector table, NVIC, SysTick"),
  rule(/register là ô nhớ|memory-mapped/i, "Peripheral được đặt vào không gian địa chỉ của CPU. Đọc/ghi một địa chỉ đặc biệt sẽ đọc trạng thái hoặc ra lệnh cho phần cứng, không giống RAM thường.", "Register có thể read-only, write-only, W1C hoặc có side effect khi đọc. Vì vậy kiểu access và mô tả field quan trọng ngang địa chỉ.", "ARM memory model + RM register descriptions", "memory-mapped peripheral, access type, side effect"),
  rule(/volatile|__IO|__I\b|__O\b/i, "volatile yêu cầu compiler thực hiện lần đọc/ghi thật mỗi khi source code yêu cầu. Nó cần thiết vì phần cứng có thể đổi register ngoài luồng chương trình.", "volatile không làm thao tác atomic và không chữa race giữa main/ISR. __I/__O/__IO chỉ biểu đạt quyền đọc/ghi để compiler bắt lỗi tốt hơn.", "CMSIS-Core access qualifiers; ARM memory model", "__I __O __IO volatile atomicity"),
  rule(/mask|shift|RMW|read-modify-write/i, "Mask chọn đúng nhóm bit; shift đưa giá trị vào đúng vị trí. Read-modify-write dùng khi cần thay một field nhưng giữ các field R/W khác.", "Quy trình là đọc snapshot, xóa field bằng AND với mask đảo, OR giá trị đã shift rồi ghi lại. Không dùng RMW cho write-only command hoặc W1C.", "RM · field bit range và access type", "field mask shift read modify write"),
  rule(/W1C/i, "W1C nghĩa là ghi số 1 vào bit cần xóa cờ; ghi 0 để nguyên. Đây là lệnh clear chứ không phải ô nhớ R/W thông thường.", "Dùng `REG = mask`. `REG &= ~mask` có thể đọc các cờ đang bằng 1 rồi ghi lại sai semantics hoặc xóa nhầm sự kiện mới.", "RM · register access type W1C", "W1C write one to clear"),
  rule(/access type|reset value/i, "Access type cho biết CPU được đọc/ghi thế nào; reset value cho biết trạng thái phần cứng trước init. Bỏ qua hai cột này dễ tạo code tưởng đúng nhưng không có tác dụng.", "Một field RO không thể cấu hình; W1C cần cách clear riêng; reset value quyết định có cần ghi hay không. Ghi toàn register bằng literal có thể phá reserved/default fields.", "RM · register table của peripheral", "access type reset value reserved bit"),
  rule(/chip-specific|generic chapter|S32K144/i, "IP generic mô tả khối phần cứng dùng lại trên nhiều chip; phần chip-specific nói chính xác S32K144 đã nối và giới hạn nó thế nào.", "Khi hai phần khác nhau, restriction của chip-specific thắng. Ví dụ ADC generic có thể minh họa field/channel rộng hơn implementation S32K144.", "S32K1xx RM · device-specific configuration chapter trước peripheral chapter", "device-specific configuration, implementation note"),
  rule(/contract|precondition|timeout|validation/i, "API contract nói caller phải đưa gì, nhận gì, hàm có block không và lỗi được báo thế nào. Người dùng driver không cần đoán hành vi.", "Validate pointer/instance/channel/state trước access. Mọi vòng chờ phần cứng cần timeout để clock hoặc wiring sai không treo toàn hệ thống.", "Software design + RM operation states", "precondition postcondition timeout error code"),
  rule(/primitive|non-blocking|blocking/i, "Primitive là thao tác nhỏ phản ánh state machine phần cứng như Start, IsDone, Read. Hàm blocking chỉ ghép các primitive với timeout.", "Tách như vậy cho phép cùng driver chạy polling, scheduler hoặc interrupt mà không nhân đôi register logic.", "RM · peripheral operation sequence", "start status result state machine"),
  rule(/package pin|port pin|alternate function|Pin ID/i, "Một chân có nhiều tên ở các lớp khác nhau: số chân package, PTC14, chức năng ADC0_SE12 và net trên board. Không tên nào tự thay thế tên còn lại.", "Đi từ schematic net → MCU pin → bảng pin mux → PORT/bit → peripheral signal. Pin ID `(port<<5)|bit` chỉ là encoding software, không chứa polarity.", "Schematic SCH-28810 + RM Ch.4 signal multiplexing", "pinout package Q100 PTC14 ALT function"),
  rule(/\bPCC\b|\bCGC\b|interface clock/i, "PCC giống cầu dao cấp clock cho từng peripheral. Khi CGC=0, block có thể không nhận được giao dịch/configuration dù địa chỉ C vẫn tồn tại.", "Mỗi PCC slot thuộc một instance. Bật CGC trước khi dùng PORT; với module có PCS/divider phải cấu hình source khi gate tắt và tuân restriction của module.", "S32K1xx RM · Ch.29 PCC · PDF p.648+, PCC_PORTD p.655", "PCC CGC PCS PCD FRAC peripheral index"),
  rule(/PORT_PCR|\bPCR\b|MUX|pull|filter|drive|IRQC/i, "PCR là bảng điều khiển phần pad của từng chân. Nó chọn chân nối vào GPIO hay peripheral nào, có pull/filter/drive gì và cạnh nào tạo interrupt.", "PCRn nằm trong PORT block, mỗi phần tử cách 4 byte. MUX chọn alternate function; PE/PS điều khiển pull; PFE lọc thụ động; DSE ảnh hưởng drive; IRQC cấu hình interrupt/DMA request. Chỉ bật field thật sự cần và giữ reserved bits đúng yêu cầu.", "S32K1xx RM · Ch.12 PORT · Pin Control Register n · PDF p.240–242", "Pin Control Register n MUX PE PS PFE DSE IRQC ISF"),
  rule(/PDDR|direction|input\/output/i, "PDDR chọn bộ đệm output có được phép lái chân hay không: bit 0 là input, bit 1 là output. Nó không tự chọn level HIGH/LOW.", "Output latch và direction là hai trạng thái riêng. Hãy preload PDOR/PSOR/PCOR trước rồi mới set PDDR để tránh một xung glitch không mong muốn.", "S32K1xx RM · Ch.13 GPIO · PDDR · PDF p.263", "Port Data Direction Register PDDR"),
  rule(/PSOR|PCOR|PTOR|atomic/i, "PSOR, PCOR và PTOR là các cổng lệnh: ghi 1 vào mask để set, clear hoặc toggle bit tương ứng. Ghi 0 không tác động.", "Chúng tránh chuỗi đọc-sửa-ghi trên PDOR. Vì không cần đọc snapshot, cập nhật một bit không làm mất thay đổi bit khác vừa được ISR hoặc luồng khác thực hiện.", "S32K1xx RM · Ch.13 GPIO · PSOR p.259, PCOR p.260, PTOR p.261", "Port Set Output Register Port Clear Output Register Port Toggle Output Register"),
  rule(/PDIR|logic pin/i, "PDIR là ảnh chụp mức điện hiện tại ở input path. Giá trị 1 chỉ có nghĩa điện áp được nhận là HIGH, chưa có nghĩa nút đang được nhấn.", "Board layer kết hợp PDIR với pull và polarity để trả `pressed=true/false`. Nếu pin floating, PDIR có thể đổi ngẫu nhiên nên cần pull nội hoặc pull ngoài phù hợp.", "S32K1xx RM · Ch.13 GPIO · PDIR · PDF p.262; schematic cho polarity", "Port Data Input Register PDIR input buffer"),
  rule(/ISFR|\bISF\b/i, "ISFR cho biết chân nào trong PORT đã phát sinh yêu cầu interrupt. Một bit set là bằng chứng peripheral source đã nhìn thấy edge/level.", "ISFR/ISF dùng W1C. ISR nên snapshot, xử lý đúng mask rồi ghi mask để clear; không clear bằng RMW. Nếu ISFR set nhưng ISR không chạy, lỗi nằm ở NVIC/vector/global masking phía sau.", "S32K1xx RM · Ch.12 PORT · ISFR PDF p.247", "Interrupt Status Flag Register ISFR ISF W1C"),
  rule(/struct|reserved gap|offsetof|Static_assert|PCR\[32\]/i, "C struct chỉ đúng khi byte layout giống hệt silicon. Tên đẹp không cứu được một field đặt sai offset.", "Dùng mảng cho register lặp, reserved byte cho khoảng trống, rồi `_Static_assert(offsetof(...))`. PCR[32] chiếm 0x00–0x7C; ISFR ở 0xA0 nên giữa chúng phải có gap đúng.", "RM Ch.12/13 · register memory map", "register memory map offset reserved offsetof"),
  rule(/preload|glitch|Default input/i, "Glitch là xung ngắn xuất hiện trong lúc cấu hình, có thể vô hại với LED nhưng nguy hiểm với enable, chip-select hoặc công suất.", "Giữ direction input, đặt output latch về mức an toàn, sau đó mới bật PDDR output. Khi shutdown làm ngược theo yêu cầu tải.", "RM GPIO operation + schematic polarity/tải", "safe state preload output latch glitch"),
  rule(/Decode pin|validate trước access/i, "Pin ID do phần mềm encode phải được tách thành port và bit rồi kiểm tra phạm vi trước khi dùng làm index. Dữ liệu sai không được phép biến thành một lần ghi MMIO sai địa chỉ.", "Kiểm tra port A–E, bit 0–31, option hợp lệ và pointer trước khi tra bảng PORT/GPIO/PCC instance. Chỉ sau khi mọi validation pass mới bật clock hoặc ghi PCR.", "Driver contract + RM Ch.3/12/13/29", "pin decode validation range before register access"),
  rule(/common-anode|pin 0 bật|pin 1 tắt/i, "LED common-anode có cực dương nối nguồn chung; MCU bật màu bằng cách kéo cực âm xuống LOW. Vì vậy giá trị logic ON bị đảo so với mức điện ghi ra chân.", "Generic GPIO_Write vẫn dùng 0=LOW, 1=HIGH. Board_LedSet mới thực hiện phép đảo active-low dựa trên schematic; không nhét đặc tính LED vào GPIO driver.", "SCH-28810 Rev.B · RGB LED sheet", "RGB common anode active low LED resistor"),
  rule(/PE bật pull|pull-up|pull-down|external pull/i, "Pull là điện trở yếu giữ input ở mức xác định khi không ai chủ động lái. Pull-up giữ HIGH; pull-down giữ LOW.", "PCR.PE bật pull nội, PCR.PS chọn hướng. Nếu schematic đã có pull ngoài, phải đánh giá xung đột/divider trước khi bật pull nội; không bật theo thói quen.", "RM Ch.12 PCR PE/PS + schematic resistor network", "PE PS pull enable pull select"),
  rule(/IRQ number|ISER index|callback table|callback/i, "IRQ number định danh nguồn interrupt ngoài core; exception number còn cộng phần exception hệ thống. Callback là hàm application đăng ký để driver báo sự kiện mà không phụ thuộc ngược vào app.", "NVIC ISER index = IRQn/32, bit = IRQn%32. Vector phải trỏ đúng handler; handler clear source và xuất bản event/callback ngắn, còn debounce chạy ngoài ISR.", "ARM DDI0403E B1.5/B3.4 + RM device IRQ table", "IRQn exception number NVIC ISER vector callback"),
  rule(/SAR ADC|12-bit|0…4095|LSB/i, "ADC lấy một điện áp và trả một mã số. 12-bit tạo 4096 mức từ 0 đến 4095; mã này chỉ có ý nghĩa khi biết VREF.", "SAR dùng sample-and-hold rồi so sánh tuần tự. LSB xấp xỉ `(VREFH−VREFL)/4096`; raw sang mV cần VREF thực đo và phải chấp nhận quantization/error.", "S32K1xx Datasheet Rev.15 · ADC p.52–56; RM Ch.44", "SAR resolution quantization VREF LSB"),
  rule(/sample capacitor|source impedance|VADIN/i, "ADC không nhìn nguồn analog một cách vô hạn trở kháng: tụ sample bên trong phải được nạp trong một khoảng thời gian. Nguồn quá yếu hoặc sample quá ngắn làm kết quả thấp/sai.", "Kiểm tra source impedance, sample time, ADCK và input range trong Datasheet. VADIN phải nằm trong VREFL…VREFH trong điều kiện được phép.", "S32K1xx Datasheet Rev.15 · ADC electrical specifications PDF p.52–56", "input capacitance source resistance sample time VADIN"),
  rule(/ADC0_SE12|external channel|Unavailable channels/i, "ADC0_SE12 nghĩa là channel single-ended số 12 của instance ADC0. Nó không tự khẳng định board đang nối gì vào đó.", "Schematic nối potentiometer tới PTC14; bảng pin mux/channel xác nhận PTC14 có đường ADC0_SE12. Channel không có trên package phải coi reserved.", "SCH-28810 p.3/p.6 + RM Ch.4/43", "PTC14 ADC0_SE12 channel assignment"),
  rule(/SC1|ADCH|COCO|RA|Write SC1|Read RA/i, "SC1 chọn channel và bắt đầu conversion trong software-trigger mode; COCO báo xong; RA giữ kết quả. Đây là state machine Start → Wait → Consume.", "Ghi SC1 khi conversion đang chạy có thể abort/replace. Đọc RA consume kết quả và clear COCO, vì vậy chỉ một owner được đọc RA trong polling/ISR/DMA policy.", "S32K1xx RM · Ch.43/44 · SC1, R register semantics", "SC1 ADCH COCO result R conversion complete"),
  rule(/R\[16\]|0x48.*0x84/i, "ADC có nhiều result slot tương ứng các SC1 slot. `R[16]` trong struct phải phản ánh đúng vùng offset, không phải một mảng RAM tùy ý.", "R0 bắt đầu 0x48 và các phần tử word cách 4 byte tới R15. Đọc Rn có side effect liên quan COCO của slot n; reserved gap trước/sau mảng phải giữ đúng.", "S32K1xx RM Ch.43/44 · ADC register map và Rn", "ADC result register Rn offset 0x48"),
  rule(/UNINIT.*READY.*CONVERTING/i, "State machine ngăn API được gọi sai thời điểm: chưa init không được start; đang convert không được cấu hình lại; chỉ có result hoàn tất mới được read.", "Init thành công chuyển UNINIT→READY; Start hợp lệ chuyển READY→CONVERTING; COCO/read hoặc lỗi/timeout đưa state theo policy. State software phải đối chiếu được với COCO/CAL/hardware mode.", "RM ADC operation sequence + driver API contract", "ADC driver state machine uninit ready converting"),
  rule(/FIRCDIV|ADCK|ADICLK|ADIV|clock/i, "Peripheral chỉ chạy đúng khi biết clock thực tới nó. Tên clock source chưa phải frequency; phải theo toàn bộ chuỗi source → divider → PCC → peripheral divider.", "Tính frequency ở từng nút, kiểm tra gate/source/divider và so với Datasheet. Sau khi đổi system clock phải tính lại timeout, baud, sample rate và PWM.", "RM Ch.27–29 + peripheral clock section; Datasheet timing limits", "clock source divider PCC PCS peripheral functional clock"),
  rule(/Đổi PCS|module disabled/i, "PCS chọn nguồn clock của peripheral. Đổi nguồn khi module đang chạy có thể tạo clock không liên tục hoặc vi phạm restriction.", "Tắt CGC/disable hoặc đưa module về trạng thái quiescent theo RM, cấu hình PCS/divider, rồi mới bật gate và xác nhận frequency. Không dùng một sequence PCC cho mọi loại peripheral.", "S32K1xx RM Ch.29 PCC · In-use/clock selection restrictions", "PCC PCS change clock source module disabled"),
  rule(/CFG1|CFG2|MODE|SMPLTS|REFSEL|ADTRG/i, "Các field cấu hình ADC quyết định resolution, clock divider, sample duration, reference và software/hardware trigger. Chúng thay đổi cả độ chính xác lẫn timing.", "Chọn mode và clock từ yêu cầu đo, tính conversion budget, rồi mới ghi field bằng mask. ADTRG=0 dùng SC1 start; ADTRG=1 chờ hardware trigger.", "S32K1xx RM Ch.43/44 + Datasheet ADC specifications", "ADC CFG1 CFG2 SC2 MODE ADIV SMPLTS REFSEL ADTRG"),
  rule(/Encoding không phải enum|field encoding/i, "Giá trị ghi vào field thường là mã hóa phần cứng, không nhất thiết bằng con số con người đang nghĩ tới. Ví dụ một mã MODE hoặc divider có thể đại diện 8/10/12-bit hay chia 1/2/4/8.", "Tạo macro từ bảng encoding của RM, không cast enum tùy ý vào field. Unit test từng lựa chọn bằng expected mask/value và đọc lại register sau init.", "RM · field value description table", "field encoding reserved value reset value"),
  rule(/Sample time là thời gian vật lý/i, "SMPLTS không chỉ là một con số đẹp trong register; nó quyết định tụ sample-and-hold có bao nhiêu chu kỳ để nạp từ nguồn analog.", "Từ ADCK và encoding SMPLTS, tính thời gian acquisition; so với source impedance và Datasheet. Nếu raw phụ thuộc tốc độ hoặc thấp hơn kỳ vọng, tăng sample time là một thí nghiệm chẩn đoán có cơ sở.", "RM ADC CFG2.SMPLTS + Datasheet ADC source resistance/acquisition", "SMPLTS sample time acquisition source resistance"),
  rule(/calibration|\bCAL\b|AVGE|AVGS/i, "Calibration để ADC tự đo và bù sai số nội sau reset. Đây là một operation có bắt đầu, trạng thái chờ và điều kiện thất bại, không phải một bit cấu hình tĩnh.", "Thiết lập average theo yêu cầu, set CAL, không sửa ADC register trong lúc chạy và chờ CAL clear với timeout. Chỉ chuyển driver sang READY khi thành công.", "RM Ch.44 calibration sequence + Datasheet calibration clock limit", "ADC calibration CAL CALF AVGE AVGS"),
  rule(/AIEN|average|continuous|ADCO/i, "Interrupt, hardware averaging và continuous conversion là ba tính năng khác nhau. Bật từng tính năng sau khi polling cơ bản đã pass để biết thay đổi nào gây lỗi.", "AIEN đổi owner kết quả sang ISR; averaging tăng latency; ADCO liên tục tạo sample nên cần buffer và overrun policy. Không để main và ISR cùng đọc RA.", "RM Ch.44 · SC1.AIEN và SC3 AVGE/AVGS/ADCO", "ADC interrupt hardware average continuous conversion"),
  rule(/ISR phải consume|consume result|clear source/i, "Mỗi interrupt phải có một hành động làm nguồn ngừng pending: đọc result, clear W1C hoặc acknowledge theo đúng peripheral. Chỉ return khỏi handler không tự giải quyết nguồn.", "Xác định duy nhất owner của dữ liệu. Với ADC, đọc RA có thể clear COCO; với PORT/CAN, ghi mask W1C clear flag. Snapshot trước khi clear nếu cần chẩn đoán và không để main đọc cạnh tranh.", "RM source-flag semantics + ARM exception return", "interrupt source clear acknowledge consume result"),
  rule(/Evidence ba tầng/i, "Một driver chạy được cần ba loại bằng chứng: register đúng, tín hiệu điện đúng và hành vi sản phẩm đúng. Chỉ thấy một dòng printf chưa chứng minh hai tầng còn lại.", "Lưu snapshot clock/mux/config/status; đo pin/VREF/waveform; ghi test output theo min-mid-max hoặc failure injection. Ba tầng giúp khoanh vùng lỗi software, peripheral hay board.", "RM + Datasheet + schematic + debugger/oscilloscope evidence", "register evidence electrical evidence behavior evidence"),
  rule(/PDB0|PDB1|default\/suggested|pre-trigger/i, "PDB là bộ lập lịch trigger có delay và handshake cho ADC. PDB0 ghép ADC0, PDB1 ghép ADC1 trong scheme được RM khuyến nghị.", "Trigger mở một chu kỳ; pre-trigger chọn SC1 slot bắt đầu conversion. COCO phản hồi để nhả lock, giúp xếp nhiều conversion mà CPU không canh từng lần.", "RM Ch.43 PDF p.1227–1235 + Ch.46 PDB", "PDB ADC pre-trigger lock ACK COCO sequence error"),
  rule(/TRGMUX|bốn pre-triggers/i, "TRGMUX là ma trận nối nguồn trigger phần cứng tới đích. Nó route tín hiệu; nó không tự tạo sample rate hoặc bảo đảm conversion kịp xong.", "ADC path qua TRGMUX hỗ trợ tối đa bốn pre-trigger. Software phải chọn SIM_ADCOPT đúng path và bảo đảm spacing vì không có handshake PDB tương đương.", "RM Ch.19 TRGMUX + Ch.43 PDF p.1227–1235", "TRGMUX ADCxTRGSEL SWPRETRG pretrigger"),
  rule(/DMAEN|DMA|DMAMUX|buffer|spacing\/sample rate/i, "DMA chuyển dữ liệu giữa peripheral và RAM mà CPU không copy từng mẫu. DMAMUX chọn nguồn request; eDMA TCD mô tả địa chỉ và vòng lặp transfer.", "ADC completion phát request khi DMAEN bật. TCD cần source RA cố định, destination tăng, transfer size đúng và major-loop/ownership policy. Sample period phải dài hơn conversion path và buffer phải được consume trước khi ghi đè.", "RM Ch.17 DMAMUX, Ch.18 eDMA, Ch.43/44 ADC", "DMAMUX source eDMA TCD SADDR DADDR NBYTES CITER BITER"),
  rule(/dominant|recessive|arbitration|Identifier nhỏ/i, "CAN cho phép nhiều node cùng bắt đầu phát. Bit dominant 0 ghi đè recessive 1, nên node thấy bus khác bit mình gửi sẽ dừng mà không phá frame thắng.", "Identifier được phát từ bit cao; ID số nhỏ thường có dominant sớm hơn nên ưu tiên cao hơn. Đây là phân xử bitwise, không phải hai frame va chạm rồi retry ngẫu nhiên.", "RM Ch.55 FlexCAN protocol overview; CAN protocol concepts", "CAN dominant recessive nondestructive arbitration identifier"),
  rule(/ACK slot|tự ACK|ACKERR/i, "Node nhận frame hợp lệ kéo ACK slot dominant để báo đã có ít nhất một peer nhận. Node phát không tự ACK frame của chính nó ở normal bus.", "Một node đơn có thể phát lặp và tăng error counter vì ACKERR dù waveform TX tồn tại. Internal loopback là bài test khác và không chứng minh physical network.", "RM Ch.55 ESR1 ACKERR và protocol operation", "CAN ACK slot ACKERR single node"),
  rule(/TEC|REC|error-active|error-passive|bus-off/i, "CAN đếm lỗi phát và nhận để cô lập node gây nhiễu. Trạng thái chuyển dần từ active sang passive và bus-off thay vì để một node phá mạng vô hạn.", "Đọc ECR cùng ESR1 và timestamp. Recovery phải là policy có điều kiện; không reset controller ngay lập tức vì sẽ xóa bằng chứng root cause.", "RM Ch.55 ECR/ESR1/error confinement", "TXERRCNT RXERRCNT FLTCONF bus off recovery"),
  rule(/transceiver|CANH|CANL|TXD|RXD|PTE5|PTE4/i, "FlexCAN trong MCU tạo logic TX/RX, còn transceiver biến nó thành điện áp vi sai CANH/CANL chịu được bus. Không nối chân MCU trực tiếp vào hai dây bus.", "Debug theo tầng: CAN0_TX → TXD → CANH/CANL → RXD → CAN0_RX. Điểm đầu tiên mất waveform chỉ ra layer lỗi: mux/controller, transceiver/power/standby hay cable/termination.", "SCH-28810 Rev.B p.3/p.5 + RM Ch.4/55", "PTE5 CAN0_TX PTE4 CAN0_RX MCZ33903 CANH CANL"),
  rule(/termination|120Ω|60Ω/i, "CAN cần 120 Ω ở đúng hai đầu vật lý của trunk để giảm phản xạ. Không phải mỗi node đều gắn một điện trở 120 Ω.", "Khi tắt nguồn và có đúng hai terminator 120 Ω song song, đo giữa CANH-CANL xấp xỉ 60 Ω. Jumper/stuffing option trên board thật phải được xác minh.", "Schematic transceiver/termination sheet + physical measurement", "CAN termination 120 ohm 60 ohm trunk stub"),
  rule(/base address|offset|mailbox|stride|offsetof/i, "Base chọn instance peripheral; offset chọn register bên trong instance. Mailbox là vùng RAM phần cứng có layout cố định, không phải struct tùy ý.", "Địa chỉ = base + offset; MBn = MB0 + n×stride. Reserved gap và stride phải được chứng minh bằng offsetof/static assert trước khi driver chạy.", "RM Ch.3 memory map + Ch.55 FlexCAN register/MB map", "FlexCAN base offset message buffer stride"),
  rule(/Freeze|FRZACK|HALT|NOTRDY|MDIS/i, "Freeze mode là trạng thái an toàn để sửa cấu hình FlexCAN. Yêu cầu freeze không có nghĩa module đã vào freeze ngay; phải chờ acknowledgement.", "Mở clock/module theo sequence, set FRZ/HALT, chờ FRZACK và NOTRDY phù hợp, cấu hình rồi clear HALT và chờ sẵn sàng. Mọi wait cần timeout/snapshot lỗi.", "RM Ch.55 FlexCAN initialization sequence · MCR", "FlexCAN freeze mode FRZ HALT FRZACK NOTRDY"),
  rule(/bit timing|TQ|PSEG|PROPSEG|PRESDIV|sample point/i, "Một CAN bit được chia thành nhiều time quantum để node lấy mẫu ở vị trí có chủ đích. Không thể copy timing khi protocol clock khác.", "Tính TQ từ clock và prescaler; tổng SyncSeg+PropSeg+PSEG1+PSEG2 tạo bit time. Kiểm tra bitrate, sample point, RJW và field encoding `value-1` theo RM.", "RM Ch.55 CTRL1/CBT + actual protocol clock", "CAN bit timing time quantum sample point PRESDIV PROPSEG PSEG1 PSEG2 RJW"),
  rule(/\bCS\b|\bDLC\b|\bCODE\b|WORD0|WORD1|Standard ID/i, "Message buffer chứa control/status, identifier và payload. CODE là trạng thái ownership giữa CPU và FlexCAN, không chỉ là kiểu frame.", "CPU chỉ ghi MB khi CODE cho phép; standard ID nằm đúng bit field; DLC classic 0–8; byte packing phải test bằng pattern không đối xứng. IFLAG báo MB hoàn tất.", "RM Ch.55 message buffer structure and CODE tables", "FlexCAN MB CS CODE DLC ID WORD0 WORD1"),
  rule(/IMASK1|IFLAG1|ESR1|ECR|CRCERR|FRMERR|STFERR/i, "IMASK cho phép nguồn ngắt; IFLAG cho biết mailbox pending; ESR1/ECR mô tả protocol error và counter. Một cờ ‘CAN_FAIL’ chung làm mất dữ liệu chẩn đoán.", "ISR snapshot status, clear đúng W1C và enqueue event. Ngoài ISR mới phân loại ACK, CRC, form, stuffing, warning hay bus-off và thực hiện recovery policy.", "RM Ch.55 IMASK1/IFLAG1/ESR1/ECR", "FlexCAN interrupt error status W1C"),
  rule(/loopback|hai-node|analyzer|Failure injection/i, "Mỗi tầng test chứng minh một phần khác nhau: loopback chứng minh controller/mailbox; waveform chứng minh pin/transceiver; hai node chứng minh ACK/arbitration/network.", "Không được dùng loopback để kết luận bus thật tốt. Inject mất peer, sai bitrate hoặc termination rồi lưu ESR1/ECR và analyzer trace để tạo chữ ký lỗi.", "RM Ch.55 test modes + schematic + measurement evidence", "FlexCAN loopback external bus two node analyzer"),
];

const defaultSource = (module) => module.phase === "can"
  ? "S32K1xx RM Ch.55 + Datasheet + schematic"
  : module.phase === "adc" || module.phase === "advanced"
    ? "S32K1xx RM Ch.43–49 + Datasheet ADC/timing"
    : module.phase === "gpio"
      ? "S32K1xx RM Ch.12/13/29 + schematic"
      : "S32K1xx RM + ARM DDI0403E.e theo source matrix";

export function explainConcept(module, concept) {
  const matched = rules.find((item) => item.pattern.test(concept));
  if (matched) return matched;
  const registerNames = (module.registers || []).slice(0, 4).map((row) => row[0]).join(", ") || "register inventory của bài";
  const flow = (module.dependencies || []).slice(0, 5).join(" → ") || "requirement → configuration → operation → status → evidence";
  return {
    plain: `Đây là một kết luận cần được chứng minh, không phải câu để học thuộc. Hãy diễn đạt lại bằng lời của bạn và chỉ ra nó thay đổi hành vi phần cứng nào.`,
    mechanism: `Trong bài này, đặt kết luận vào đường ${flow}. Sau đó đối chiếu ${registerNames}, thực hiện một phép đo hoặc register snapshot để chứng minh.`,
    source: defaultSource(module),
    search: concept.replace(/[.…]/g, " ").trim(),
  };
}
